import{_ as l,o as i,c as a,a2 as r}from"./chunks/framework.QCr1ZR1X.js";const P=JSON.parse('{"title":"第1章 互联网基础（教师用书）","description":"","frontmatter":{},"headers":[],"relativePath":"teacher/ch1/教师用书-第1章-互联网基础.md","filePath":"teacher/ch1/教师用书-第1章-互联网基础.md","lastUpdated":1786967935000}'),o={name:"teacher/ch1/教师用书-第1章-互联网基础.md"};function e(n,t,d,h,s,u){return i(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="第1章-互联网基础-教师用书" tabindex="-1">第1章 互联网基础（教师用书） <a class="header-anchor" href="#第1章-互联网基础-教师用书" aria-label="Permalink to &quot;第1章 互联网基础（教师用书）&quot;">​</a></h1><blockquote><p>本章定位：全书的技术基石 课时安排：8课时（理论4 + 实践4） 学情分析：学生通常有上网经验，但对原理一无所知；对动手操作兴趣高，对纯理论有畏难情绪</p></blockquote><hr><h2 id="一、本章教学目标" tabindex="-1">一、本章教学目标 <a class="header-anchor" href="#一、本章教学目标" aria-label="Permalink to &quot;一、本章教学目标&quot;">​</a></h2><h3 id="知识目标" tabindex="-1">知识目标 <a class="header-anchor" href="#知识目标" aria-label="Permalink to &quot;知识目标&quot;">​</a></h3><ol><li>了解互联网发展脉络（从ARPANET到5G，含中国部分）</li><li>理解TCP/IP四层模型与各层职责</li><li>掌握IP地址、子网掩码、网关、DNS基本概念</li><li>了解MAC地址、ARP协议、ICMP协议作用</li><li>了解互联网架构（接入网、城域网、骨干网）</li><li>了解常用应用服务与协议</li><li>了解网络安全基础（CIA、防火墙）</li></ol><h3 id="技能目标" tabindex="-1">技能目标 <a class="header-anchor" href="#技能目标" aria-label="Permalink to &quot;技能目标&quot;">​</a></h3><ol><li>能在Windows/Ubuntu双环境下查看和配置IP</li><li>能使用ping/tracert诊断网络连通性</li><li>能使用nslookup查询DNS</li><li>能配置操作系统防火墙入站/出站规则</li></ol><h3 id="素养目标" tabindex="-1">素养目标 <a class="header-anchor" href="#素养目标" aria-label="Permalink to &quot;素养目标&quot;">​</a></h3><ul><li><strong>分层思维</strong>：复杂系统通过分层分工实现高效运转</li><li><strong>排查思维</strong>：遇到问题不再只说&quot;网坏了&quot;，而是由近及远定位</li><li><strong>法治意识</strong>：网络空间不是法外之地，遵守网络安全法律法规</li><li><strong>岗位意识</strong>：从职业标准看待所学知识</li></ul><hr><h2 id="二、课时分配与教学安排" tabindex="-1">二、课时分配与教学安排 <a class="header-anchor" href="#二、课时分配与教学安排" aria-label="Permalink to &quot;二、课时分配与教学安排&quot;">​</a></h2><table tabindex="0"><thead><tr><th>课次</th><th>课时</th><th>内容</th><th>教学类型</th><th>重点/难点</th></tr></thead><tbody><tr><td>第1次课</td><td>2h</td><td>1.1 场景导入 + 互联网发展简史 + TCP/IP模型上半部分（网络接口层+网络层）</td><td>理论</td><td><strong>重点</strong>：数据包封装过程<br><strong>难点</strong>：ISP分层与网络架构</td></tr><tr><td>第2次课</td><td>2h</td><td>TCP/IP模型下半部分（传输层+应用层） + 1.3 IP地址/DNS/安全基础</td><td>理论</td><td><strong>重点</strong>：TCP/UDP区别、公网vs私有IP<br><strong>难点</strong>：NAT原理、DNS递归查询</td></tr><tr><td>第3次课</td><td>2h</td><td>1.2 实践：IP配置 + 连通诊断</td><td>理实混合</td><td><strong>重点</strong>：双环境操作对比<br><strong>难点</strong>：由近及远排查思路</td></tr><tr><td>第4次课</td><td>2h</td><td>1.4 实践：DNS查询 + 防火墙配置</td><td>实践</td><td><strong>重点</strong>：防火墙规则逻辑<br><strong>难点</strong>：入站/出站规则区别理解</td></tr></tbody></table><hr><h2 id="三、各节教学实施建议" tabindex="-1">三、各节教学实施建议 <a class="header-anchor" href="#三、各节教学实施建议" aria-label="Permalink to &quot;三、各节教学实施建议&quot;">​</a></h2><h3 id="_1-1-从一封邮件到万物互联-2课时" tabindex="-1">1.1 从一封邮件到万物互联（2课时） <a class="header-anchor" href="#_1-1-从一封邮件到万物互联-2课时" aria-label="Permalink to &quot;1.1 从一封邮件到万物互联（2课时）&quot;">​</a></h3><h4 id="教学建议" tabindex="-1">教学建议 <a class="header-anchor" href="#教学建议" aria-label="Permalink to &quot;教学建议&quot;">​</a></h4><ol><li><p><strong>开场（10分钟）</strong></p><ul><li>互动提问：&quot;你今天用了几次互联网？数据去哪儿了？&quot;</li><li>用快递单旅程动画演示，让学生直观理解</li><li><strong>工业预告</strong>要多花1分钟强调：&quot;这章知识就是工业互联网的基础，数据从设备到平台，走的也是这条路&quot;</li></ul></li><li><p><strong>互联网发展简史（25分钟）</strong></p><ul><li>重点讲&quot;开放&quot;带来的爆发，不要纠结年份细节</li><li>ARPANET&quot;LO&quot;的故事生动有趣，一定要讲，能活跃课堂</li><li>中国部分要有自豪感，强调从接入者到引领者</li><li><strong>拓展知识</strong>（互联网管理机构）作为兴趣点，不做要求</li></ul></li><li><p><strong>TCP/IP四层模型（50分钟）</strong></p><ul><li><strong>快递公司类比</strong>贯穿始终： <ul><li>寄件人=应用层</li><li>打包员=传输层</li><li>分拣员=网络层</li><li>货车/飞机=网络接口层</li></ul></li><li><strong>分层演示</strong>：4人小组，每人代表一层，传递纸条+加标签</li><li>OSI七层对照：提一句即可，不用展开</li><li>MAC地址/ARP协议：用&quot;小区广播站&quot;类比</li><li><strong>工业视角</strong>：识别设备接口是国标初级1.1的要求（为第3章打伏笔）</li></ul></li><li><p><strong>回顾反思（15分钟）</strong></p><ul><li>小组讨论：如果不分层会怎样？</li><li>请2-3组分享</li></ul></li></ol><h4 id="教学辅助资源" tabindex="-1">教学辅助资源 <a class="header-anchor" href="#教学辅助资源" aria-label="Permalink to &quot;教学辅助资源&quot;">​</a></h4><ul><li>配套视频：TCP/IP四层模型动画演示（可选）</li><li>演示工具：Wireshark抓包展示（可选，第1次课可以不操作，只展示）</li></ul><hr><h3 id="_1-2-ip配置与连通诊断-2课时实践" tabindex="-1">1.2 IP配置与连通诊断（2课时实践） <a class="header-anchor" href="#_1-2-ip配置与连通诊断-2课时实践" aria-label="Permalink to &quot;1.2 IP配置与连通诊断（2课时实践）&quot;">​</a></h3><h4 id="实践准备" tabindex="-1">实践准备 <a class="header-anchor" href="#实践准备" aria-label="Permalink to &quot;实践准备&quot;">​</a></h4><p>课前务必检查：</p><ol><li>机房电脑能否安装VMware</li><li>网络是否允许虚拟机使用桥接模式（桥接模式是必须的，否则同学之间无法互相ping）</li><li>提前制作好Ubuntu虚拟机镜像克隆，避免课上花时间安装</li><li>准备网络故障模拟场景（比如拔网线、改网关）</li></ol><h4 id="教学流程" tabindex="-1">教学流程 <a class="header-anchor" href="#教学流程" aria-label="Permalink to &quot;教学流程&quot;">​</a></h4><ol><li><p><strong>虚拟机环境回顾（10分钟）</strong></p><ul><li>检查学生是否已准备好环境</li><li>快速演示如何切换网络模式</li></ul></li><li><p><strong>任务一：查看IP配置（25分钟）</strong></p><ul><li>先Windows，后Ubuntu</li><li>关键信息标注：IP/掩码/网关/DNS</li><li><strong>互动</strong>：看看谁的IP和网关在同一网段？</li><li>&quot;小区大门&quot;类比要反复强调</li></ul></li><li><p><strong>任务二：连通诊断（40分钟）</strong></p><ul><li><strong>由近及远</strong>是核心排查思路： <ul><li>ping 127.0.0.1 （自检TCP/IP栈）</li><li>ping 网关（检查本地网络）</li><li>ping 百度（检查外网）</li><li>tracert 百度（看真实路径）</li></ul></li><li><strong>岗位衔接</strong>：工业网络故障排查决策树要重点讲！</li><li>可以故意制造几个小故障让学生练习排查</li><li>Windows和Ubuntu命令对比：<code>tracert</code> vs <code>traceroute</code></li></ul></li><li><p><strong>任务三：修改IP（演示为主，15分钟）</strong></p><ul><li>演示DHCP vs 静态IP的区别</li><li>强调工业设备通常用静态IP</li><li><strong>安全提示</strong>：不要在机房乱改IP</li><li>Ubuntu的netplan配置只做演示，不要求学生掌握</li></ul></li><li><p><strong>成果展示+评价（10分钟）</strong></p><ul><li>2-3组展示操作过程</li><li>填写实践任务评价表</li></ul></li></ol><h4 id="常见问题与解答" tabindex="-1">常见问题与解答 <a class="header-anchor" href="#常见问题与解答" aria-label="Permalink to &quot;常见问题与解答&quot;">​</a></h4><table tabindex="0"><thead><tr><th>学生问题</th><th>回答要点</th></tr></thead><tbody><tr><td>ping不通网关怎么办？</td><td>先看网线插好没，再看IP和掩码是不是同网段</td></tr><tr><td>桥接模式无法获取IP？</td><td>可能机房有IP限制，尝试NAT模式，牺牲互访功能</td></tr><tr><td>tracert中间有请求超时？</td><td>正常，路由器可能禁ping，看最后到了没</td></tr></tbody></table><hr><h3 id="_1-3-网址背后的秘密-2课时" tabindex="-1">1.3 网址背后的秘密（2课时） <a class="header-anchor" href="#_1-3-网址背后的秘密-2课时" aria-label="Permalink to &quot;1.3 网址背后的秘密（2课时）&quot;">​</a></h3><h4 id="教学建议-1" tabindex="-1">教学建议 <a class="header-anchor" href="#教学建议-1" aria-label="Permalink to &quot;教学建议&quot;">​</a></h4><ol><li><p><strong>IP地址（20分钟）</strong></p><ul><li>从&quot;记住IP太难&quot;引出域名的必要性</li><li>公网vs私有IP：用&quot;小区门牌号vs家里房间号&quot;类比</li><li>NAT：用&quot;小区快递柜&quot;类比，这个学生更容易理解</li><li><strong>进阶内容</strong>：二进制运算只提一句，学有余力的同学看拓展阅读</li></ul></li><li><p><strong>DNS（25分钟）</strong></p><ul><li><strong>电话簿类比</strong>：DNS就是查号台</li><li>演示nslookup：查百度、查学校官网、换DNS服务器（8.8.8.8）</li><li>CDN：解释为什么不同地点ping百度IP不一样</li><li>DNS劫持：演示如果hosts文件被篡改会怎样（让学生警惕钓鱼网站）</li></ul></li><li><p><strong>应用服务与协议（20分钟）</strong></p><ul><li>表格讲一遍，重点HTTP/HTTPS、DHCP</li><li>客户端-服务器模型：用&quot;餐厅吃饭&quot;类比</li><li>DHCP非常重要，强调工业设备用静态IP，日常用DHCP</li></ul></li><li><p><strong>安全基础（25分钟）</strong></p><ul><li><strong>CIA三元组</strong>：用例子讲（考试成绩=保密性，成绩不能改=完整性，查分系统不能挂=可用性）</li><li>震网病毒一定要讲！震撼案例，让学生对工业安全有直观认识</li><li><strong>法治视角</strong>：《网络安全法》《数据安全法》结合着说</li><li>防火墙：安检门类比，入站=查外来人员，出站=查出门人员</li></ul></li></ol><h4 id="思政融入设计" tabindex="-1">思政融入设计 <a class="header-anchor" href="#思政融入设计" aria-label="Permalink to &quot;思政融入设计&quot;">​</a></h4><table tabindex="0"><thead><tr><th>融入点</th><th>结合内容</th><th>教学方法</th></tr></thead><tbody><tr><td>制造强国</td><td>中国互联网从接入者到引领者，5G领跑</td><td>数据展示+小组讨论</td></tr><tr><td>网络安全法治</td><td>震网案例+网络安全法</td><td>案例分析+情景讨论</td></tr><tr><td>工程师伦理</td><td>DNS劫持、钓鱼网站的危害</td><td>角色扮演（如果你是安全工程师）</td></tr></tbody></table><hr><h3 id="_1-4-dns查询与防火墙配置-2课时实践" tabindex="-1">1.4 DNS查询与防火墙配置（2课时实践） <a class="header-anchor" href="#_1-4-dns查询与防火墙配置-2课时实践" aria-label="Permalink to &quot;1.4 DNS查询与防火墙配置（2课时实践）&quot;">​</a></h3><h4 id="教学流程-1" tabindex="-1">教学流程 <a class="header-anchor" href="#教学流程-1" aria-label="Permalink to &quot;教学流程&quot;">​</a></h4><ol><li><p><strong>任务一：DNS查询（30分钟）</strong></p><ul><li>基本查询 + 换DNS服务器 + 反向查询 + 缓存操作</li><li>演示清空缓存后访问变慢的现象</li><li>讨论：如果DNS被劫持会怎样？</li></ul></li><li><p><strong>任务二：入站规则（30分钟）</strong></p><ul><li>一步步演示创建过程</li><li><strong>验证环节</strong>：同学之间互相访问对方8080端口，看规则是否生效</li><li>这步一定要做，学生能直观看到效果</li><li>用&quot;小区门禁&quot;类比入站规则</li></ul></li><li><p><strong>任务三：出站规则（20分钟）</strong></p><ul><li>阻止ping.exe，演示效果</li><li><strong>对比总结</strong>：入站=别人连我，出站=我连别人</li><li>这个区别很多学生会搞混，多举生活例子</li></ul></li><li><p><strong>工业防火墙（10分钟）</strong></p><ul><li>对比表格一定要讲</li><li>强调&quot;默认拒绝，白名单放行&quot;是工业安全的核心</li><li>这是国标初级1.4的要求</li></ul></li><li><p><strong>Ubuntu ufw对照（可选，10分钟）</strong></p><ul><li>时间充裕就演示，否则跳过</li></ul></li></ol><h4 id="评价设计" tabindex="-1">评价设计 <a class="header-anchor" href="#评价设计" aria-label="Permalink to &quot;评价设计&quot;">​</a></h4><table tabindex="0"><thead><tr><th>评价方式</th><th>比重</th><th>评价要点</th></tr></thead><tbody><tr><td>实践操作</td><td>40%</td><td>完成所有任务，规则生效</td></tr><tr><td>小组互评</td><td>30%</td><td>协作能力，帮助同学</td></tr><tr><td>教师评价</td><td>30%</td><td>原理理解，安全意识</td></tr></tbody></table><hr><h2 id="四、本章小结与拓展" tabindex="-1">四、本章小结与拓展 <a class="header-anchor" href="#四、本章小结与拓展" aria-label="Permalink to &quot;四、本章小结与拓展&quot;">​</a></h2><h3 id="核心概念图谱" tabindex="-1">核心概念图谱 <a class="header-anchor" href="#核心概念图谱" aria-label="Permalink to &quot;核心概念图谱&quot;">​</a></h3><p>建议在黑板或PPT上画一个清晰的逻辑链条：</p><blockquote><p>用户输入网址 → DNS解析IP → TCP三次握手 → HTTP请求 → 路由转发 → 到达服务器 → 响应返回 → 页面显示</p></blockquote><h3 id="拓展活动建议" tabindex="-1">拓展活动建议 <a class="header-anchor" href="#拓展活动建议" aria-label="Permalink to &quot;拓展活动建议&quot;">​</a></h3><ol><li><strong>网络故障排查大赛</strong>：设置3-5个故障场景，学生分组排查</li><li><strong>校园网调研</strong>：看看学校网络架构，有几个网关，ISP是谁</li><li><strong>家庭网络优化项目</strong>：给家里路由器设置更安全的防火墙规则</li></ol><hr><h2 id="五、参考答案-思考与练习" tabindex="-1">五、参考答案（思考与练习） <a class="header-anchor" href="#五、参考答案-思考与练习" aria-label="Permalink to &quot;五、参考答案（思考与练习）&quot;">​</a></h2><h3 id="思考题-要点提示-鼓励学生有自己的思考" tabindex="-1">思考题（要点提示，鼓励学生有自己的思考） <a class="header-anchor" href="#思考题-要点提示-鼓励学生有自己的思考" aria-label="Permalink to &quot;思考题（要点提示，鼓励学生有自己的思考）&quot;">​</a></h3><ol><li>分层的好处是解耦、复用、分工；不分层会像让快递员一人负责收件、分拣、运输、派送全流程</li><li>宿舍WiFi通常分配192.168开头的私有IP；验证方式：查IP+网关是否同一网段，或者查看路由器管理页面</li><li>DNS劫持可能性：hosts文件被篡改、DNS服务器被攻击；排查：换8.8.8.8试试能否访问</li><li>公共WiFi风险：中间人攻击、窃听；防护：用VPN、访问HTTPS网站、不登录网银</li><li>流程：DNS解析 → TCP三次握手 → HTTP请求 → 数据封装传输 → 到达服务器 → 响应 → 页面渲染</li></ol><h3 id="选择题答案" tabindex="-1">选择题答案 <a class="header-anchor" href="#选择题答案" aria-label="Permalink to &quot;选择题答案&quot;">​</a></h3><ol><li>B　2. B　3. C　4. C　5. B　6. C　7. B　8. B　9. B　10. B</li></ol><h3 id="判断题答案" tabindex="-1">判断题答案 <a class="header-anchor" href="#判断题答案" aria-label="Permalink to &quot;判断题答案&quot;">​</a></h3><ol><li>×（回环地址）　2. √　3. √　4. ×（UDP无连接）　5. ×（双向都重要）</li><li>√　7. ×（IP→MAC）　8. √（端口不同）　9. √　10. ×（工业设备通常静态IP）</li></ol><hr><h2 id="六、教学反思要点" tabindex="-1">六、教学反思要点 <a class="header-anchor" href="#六、教学反思要点" aria-label="Permalink to &quot;六、教学反思要点&quot;">​</a></h2><p>课后请思考并记录：</p><ol><li>学生对哪部分最感兴趣？哪部分最困惑？</li><li>实践环节时间够吗？需要调整任务顺序吗？</li><li>类比效果如何？有没有更贴切的本地例子？</li><li>工业场景的融入学生能理解吗？需要增加更多案例吗？</li></ol>',60)])])}const b=l(o,[["render",e]]);export{P as __pageData,b as default};
